import java.util.*;
class Solution {boolean ok(int[][] d,int x){int n=d.length;int[] c=new int[n],q=new int[n];Arrays.fill(c,-1);for(int s=0;s<n;s++)if(c[s]<0){int head=0,end=1;q[0]=s;c[s]=0;while(head<end){int u=q[head++];for(int v=0;v<n;v++)if(v!=u&&d[u][v]<x){if(c[v]<0){c[v]=c[u]^1;q[end++]=v;}else if(c[v]==c[u])return false;}}}return true;}public int maxPartitionFactor(int[][] points){int n=points.length;if(n==2)return 0;int[][] d=new int[n][n];int max=0;for(int i=0;i<n;i++)for(int j=0;j<i;j++){d[i][j]=d[j][i]=Math.abs(points[i][0]-points[j][0])+Math.abs(points[i][1]-points[j][1]);max=Math.max(max,d[i][j]);}int l=0,r=max+1;while(l+1<r){int m=(l+r)/2;if(ok(d,m))l=m;else r=m;}return l;}}